13	// Shared by the suites that need a real upgrade over a real socket, which no double can stand in for.
14	
15	const servers: Array<{stop: () => Promise<void>}> = [];
16	const clients: WebSocket[] = [];
17	
18	/** An orchestrator that answers once and stops, which is what commits the turn's assistant entry. */
19	export const answeringOrchestrator: ChatOrchestrator = {
20	  processMessage: async () => 'hi',
21	  async *processMessageStream(): AsyncGenerator<MessageChunk> {
22	    yield {type: 'text', text: 'hi'};
23	    yield {type: 'stop', stopReason: 'end_turn'};
24	  },
25	};
26	
27	/** Starts an engine on an ephemeral port and returns the URL a client should open. */
28	export async function startEngine(
29	  sessionStore: SessionStore,
30	  onDisconnect?: (sessionId: string) => void
31	): Promise<string> {
32	  const {url} = await startEngineWith({sessionStore, onDisconnect});
33	  return url;
34	}
35	
36	/** Starts an engine with whatever a suite overrides, returning the server itself beside the URL a client should open. */
37	export async function startEngineWith(
38	  options: Partial<HalServerOptions> & Pick<HalServerOptions, 'sessionStore'>
39	): Promise<{url: string; hal: HalServer}> {
40	  const hal = createServer({
41	    app: (() => undefined) as unknown as Express,
42	    wsAuth: async () => ({id: 'u1'}),
43	    orchestrator: answeringOrchestrator,
44	    ...options,
45	  });
46	  await hal.start(0);
47	  servers.push(hal);
48	  const {port} = hal.server.address() as AddressInfo;
49	  return {url: `ws://127.0.0.1:${port}/hal/ws/c1`, hal};
50	}
51	
52	/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
53	export function connectClient(url: string, token = 't'): WebSocket {
54	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
55	  clients.push(client);
56	  return client;
57	}
58	
59	/** A promise a test settles by hand, to hold a stream or a hook at a point of its choosing. */
60	export function deferred(): {until: Promise<void>; release: () => void} {
61	  let release = (): void => undefined;
62	  const until = new Promise<void>(resolve => {
63	    release = resolve;
64	  });
65	  return {until, release};
66	}
67	
68	/** Resolves with every frame type seen up to and including the first `until` frame. */
69	export function framesUntil(client: WebSocket, until: string): Promise<string[]> {
70	  const seen: string[] = [];
71	  return new Promise<string[]>(resolve => {
72	    client.on('message', raw => {
73	      const {type} = JSON.parse(String(raw)) as {type: string};
74	      seen.push(type);
75	      if (type === until) resolve(seen);
76	    });
77	  });
78	}
79	
80	/** Opens a client that asks one question the moment the socket opens, resolving on the first `until` frame. */
81	export function askOnOpen(
82	  url: string,
83	  {until = 'stream_end', token}: {until?: string; token?: string} = {}
84	): {client: WebSocket; finished: Promise<string[]>} {
85	  const client = connectClient(url, token);
86	  const finished = framesUntil(client, until);
87	  client.on('open', () => client.send(JSON.stringify({type: 'user_message', content: 'hello'})));
88	  return {client, finished};
89	}
