91	/** The session id the client's `connected` frame announces, read after the fact; attach it before any frame arrives. */
92	export function announcedId(client: WebSocket): () => string {
93	  let sessionId = '';
94	  client.on('message', raw => {
95	    const frame = JSON.parse(String(raw)) as {type: string; sessionId?: string};
96	    if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
97	  });
98	  return () => sessionId;
99	}
100	
101	/** Tears every socket and server down, so a red test reports instead of hanging the run. */
102	export async function stopEngines(): Promise<void> {
103	  for (const client of clients.splice(0)) client.terminate();
104	  for (const hal of servers.splice(0)) await hal.stop();
105	}
106	
107	/** The one session a store holds, for asserting what survived a close. */
108	export async function onlySession(store: SessionStore, sessionId: string): Promise<ChatSession | undefined> {
109	  return (await store.get(sessionId)) as ChatSession | undefined;
110	}
111	
112	/** A store with only the required members, so an optional method can be added, replaced, or left out per test. */
113	export function delegatingStore(inner: InMemorySessionStore): SessionStore {
114	  return {
115	    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
116	    get: sessionId => inner.get(sessionId),
117	    delete: sessionId => inner.delete(sessionId),
118	    count: () => inner.count(),
119	    clear: () => inner.clear(),
120	  };
